from __future__ import annotations
from math import gcd, isqrt

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a

def divisors(n: int) -> list[int]:
    return [d for d in range(1, n) if n % d == 0]

def strip(a: int, b: int) -> int:
    while gcd(a, b) > 1: a //= gcd(a, b)
    return a

def primitive_part(n: int) -> int:
    r = fib(n)
    for d in divisors(n): r = strip(r, fib(d))
    return r

for n in range(13, 31):
    print(n, fib(n), primitive_part(n))

from __future__ import annotations

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n): a, b = b, a + b
    return a

def prime_factors(n: int) -> list[int]:
    ans: list[int] = []
    p = 2
    while p * p <= n:
        if n % p == 0:
            ans.append(p)
            while n % p == 0: n //= p
        p += 1
    if n > 1: ans.append(n)
    return ans

def primitive_primes(n: int) -> list[int]:
    return [p for p in prime_factors(fib(n))
            if all(fib(k) % p for k in range(1, n))]

for n in [13, 14, 15, 16, 18, 20, 24, 30]:
    print(f"F_{n} = {fib(n)}; primitive primes = {primitive_primes(n)}")

