from __future__ import annotations
from math import gcd

def complete_strip(value: int, inherited: int) -> int:
    if value <= 0 or inherited <= 0: raise ValueError("positive inputs required")
    while True:
        common = gcd(value, inherited)
        if common == 1: return value
        value //= common

def divisor_stripped_part(term: int, earlier_divisor_terms: list[int]) -> int:
    residue = term
    for earlier in earlier_divisor_terms:
        residue = complete_strip(residue, earlier)
    return residue

from __future__ import annotations
from typing import Sequence

def extract_mixed_radix(value: int, radices: Sequence[int]) -> list[int]:
    if value < 0 or any(b <= 0 for b in radices): raise ValueError("invalid input")
    capacity = 1
    for b in radices: capacity *= b
    if value >= capacity: raise ValueError("value exceeds capacity")
    digits: list[int] = []
    quotient = value
    for b in radices:
        digits.append(quotient % b)
        quotient //= b
    return digits

from __future__ import annotations
from typing import Sequence

def evaluate_mixed_radix(digits: Sequence[int], radices: Sequence[int]) -> int:
    if len(digits) != len(radices): raise ValueError("length mismatch")
    value, weight = 0, 1
    for digit, radix in zip(digits, radices):
        if radix <= 0 or not 0 <= digit < radix: raise ValueError("invalid numeral")
        value += digit * weight
        weight *= radix
    return value

